#include <stdio.h>
#include <string.h>

int oEspelho(void) {
    char palavra[50] = "";
    scanf("%49s", palavra);
    char espelho[50] = "";
    int i = 0;
    for (i = 0; palavra[i] != '\0'; i++) {
        espelho[i] = palavra[i];
    }
    espelho[i] = '\0';
    int n = i;
    for (i = 0; i < n / 2; i++) {
        char guardada = espelho[i];
        espelho[i] = espelho[n - 1 - i];
        espelho[n - 1 - i] = guardada;
    }
    return strcmp(palavra, espelho) == 0;
}
